/** The host owns connection identity; AWS owns federation and session expiry. */
import { object, string, type Infer } from "apps";
import type { ConnectContext, InteractiveInstructions, InteractiveStatus } from "apps";
import { makeIdentityCenter, AwsIdentityError } from "./identity-client.ts";
import { identityEndpoints } from "./wire.ts";
import {
  newReference,
  readPrivate,
  writePrivate,
  removePrivate,
  claimPrivate,
} from "./session-store.ts";
import { SavedSession, PendingSession, assignedInventory } from "./identity-state.ts";
import type { requirements } from "./requirements.ts";
type Context = ConnectContext<typeof requirements>;
const Fields = object({ startUrl: string({ minLength: 1 }), region: string({ minLength: 1 }) });
const owner = (ctx: Context) => {
  if (!ctx.user.id) throw new Error("AWS sign-in needs a signed-in person.");
  return ctx.user.id;
};
const form = (previous?: {
  startUrl?: string | undefined;
  region?: string | undefined;
}): InteractiveInstructions => ({
  message:
    "Use your company's AWS access portal. AWS will take you to its normal sign-in, including Okta if your company uses it. Find the start URL in your AWS access portal; the Identity Center region is shown in its settings or your existing AWS SSO configuration. It can differ from your workload region.",
  form: {
    submitLabel: "Sign in to AWS",
    fields: [
      {
        name: "startUrl",
        label: "AWS start URL",
        type: "url",
        placeholder: "https://your-company.awsapps.com/start",
        ...(previous?.startUrl === undefined ? {} : { defaultValue: previous.startUrl }),
        description: "Use your company's AWS access portal address, ending in /start.",
      },
      {
        name: "region",
        label: "Identity Center region",
        type: "text",
        placeholder: "eu-west-1",
        ...(previous?.region === undefined ? {} : { defaultValue: previous.region }),
        description:
          "The region of your AWS sign-in directory, not the region of the resources you want to use.",
      },
    ],
  },
});
const waiting = (
  pending: NonNullable<Infer<typeof PendingSession>["pending"]>,
): InteractiveInstructions => ({
  url: pending.verificationUriComplete,
  code: pending.userCode,
  expiresAt: pending.expiresAt,
  message:
    "Continue in AWS. Your company may ask you to sign in with Okta. Keep this window open until sign-in finishes.",
});
const client = (ctx: Context, input: { region: string; startUrl: string }) =>
  makeIdentityCenter({ ...input, fetch: ctx.fetch, endpoints: identityEndpoints() });
const fail = (error: unknown): InteractiveStatus => ({
  state: "failed",
  message:
    error instanceof AwsIdentityError
      ? error.message
      : "AWS sign-in could not finish. Cancel and try again. Your saved connection and default are unchanged.",
});

export const connection = {
  start: async (ctx: Context, input: { method: string; ref?: string }) => {
    const person = owner(ctx),
      reference = input.ref ?? newReference();
    const saved =
      input.ref === undefined
        ? undefined
        : await readPrivate(ctx.sql, "identity_sessions", person, reference, SavedSession);
    if (input.ref !== undefined && saved === undefined)
      throw new Error("The saved AWS session is missing. Restore it before re-signing in.");
    const attempt = newReference();
    const previous = saved?.value.session;
    await writePrivate(ctx.sql, "identity_attempts", person, attempt, {
      ref: reference,
      baseRevision: saved?.revision,
      startUrl: previous?.startUrl,
      region: previous?.region,
      nextPollAt: 0,
    });
    return { session: attempt, ...form(previous) };
  },
  submit: async (
    ctx: Context,
    input: { method: string; session: string; value: string },
  ): Promise<InteractiveStatus> => {
    const person = owner(ctx),
      retained = await readPrivate(
        ctx.sql,
        "identity_attempts",
        person,
        input.session,
        PendingSession,
      );
    if (!retained) return { state: "failed", message: "This AWS sign-in ended. Start again." };
    if (retained.value.pending)
      return { state: "waiting", instructions: waiting(retained.value.pending) };
    let fields: Infer<typeof Fields>;
    try {
      fields = Fields.parse(JSON.parse(input.value));
    } catch {
      return {
        state: "waiting",
        instructions: { ...form(), message: "Enter the AWS start URL and Identity Center region." },
      };
    }
    const release = claimPrivate(
      ctx.sql,
      "identity_attempts",
      person,
      input.session,
      retained.revision,
    );
    try {
      const aws = client(ctx, fields),
        begun = await aws.begin(),
        pending = { ...begun.client, ...begun.device };
      await writePrivate(
        ctx.sql,
        "identity_attempts",
        person,
        input.session,
        {
          ...retained.value,
          startUrl: aws.startUrl,
          region: aws.region,
          pending,
          nextPollAt: Date.now() + pending.intervalSeconds * 1000,
        },
        retained.revision,
      );
      return { state: "waiting", instructions: waiting(pending) };
    } catch (error) {
      if (
        error instanceof AwsIdentityError &&
        ["invalid_start_url", "invalid_region", "wrong_region"].includes(error.failure)
      )
        return {
          state: "waiting",
          instructions: { ...form(fields), message: error.message },
        };
      return fail(error);
    } finally {
      release();
    }
  },
  status: async (
    ctx: Context,
    input: { method: string; session: string },
  ): Promise<InteractiveStatus> => {
    const person = owner(ctx),
      retained = await readPrivate(
        ctx.sql,
        "identity_attempts",
        person,
        input.session,
        PendingSession,
      );
    if (!retained) return { state: "failed", message: "This AWS sign-in ended. Start again." };
    const pending = retained.value.pending;
    if (!pending) return { state: "waiting", instructions: form(retained.value) };
    if (Date.now() < retained.value.nextPollAt || retained.busy)
      return { state: "waiting", instructions: waiting(pending) };
    const release = claimPrivate(
      ctx.sql,
      "identity_attempts",
      person,
      input.session,
      retained.revision,
    );
    try {
      const aws = client(ctx, pending),
        polled = await aws.poll(
          pending,
          pending.deviceCode,
          pending.intervalSeconds,
          pending.expiresAt,
        );
      if (polled.state === "pending") {
        await writePrivate(
          ctx.sql,
          "identity_attempts",
          person,
          input.session,
          {
            ...retained.value,
            pending: { ...pending, intervalSeconds: polled.retryAfterSeconds },
            nextPollAt: Date.now() + polled.retryAfterSeconds * 1000,
          },
          retained.revision,
        );
        return { state: "waiting", instructions: waiting(pending) };
      }
      const previous = await readPrivate(
        ctx.sql,
        "identity_sessions",
        person,
        retained.value.ref,
        SavedSession,
      );
      if (previous?.revision !== retained.value.baseRevision)
        return {
          state: "failed",
          message:
            "Your saved AWS connection changed during sign-in. Start re-sign-in again; the newer connection is unchanged.",
        };
      const accounts = await assignedInventory(aws, polled.session, previous?.value.accounts);
      await writePrivate(
        ctx.sql,
        "identity_sessions",
        person,
        retained.value.ref,
        { ...previous?.value, session: polled.session, accounts, reauthenticationRequired: false },
        retained.value.baseRevision,
      );
      removePrivate(ctx.sql, "identity_attempts", person, input.session);
      return {
        state: "connected",
        ref: retained.value.ref,
        accountInfo: { displayName: `AWS · ${new URL(aws.startUrl).hostname.split(".")[0]}` },
      };
    } catch (error) {
      if (error instanceof AwsIdentityError && error.retryable)
        return { state: "waiting", instructions: { ...waiting(pending), message: error.message } };
      return fail(error);
    } finally {
      release();
    }
  },
  cancel: async (ctx: Context, input: { session: string }) => {
    removePrivate(ctx.sql, "identity_attempts", owner(ctx), input.session);
  },
  remove: async (ctx: Context, input: { ref: string }) => {
    removePrivate(ctx.sql, "identity_sessions", owner(ctx), input.ref);
  },
  check: async (ctx: Context, input: { ref: string }) => {
    const saved = await readPrivate(
      ctx.sql,
      "identity_sessions",
      owner(ctx),
      input.ref,
      SavedSession,
    );
    if (!saved) throw new Error("Your saved AWS session is missing. Re-sign in.");
    const aws = client(ctx, saved.value.session);
    const session =
      saved.value.session.accessTokenExpiresAt <= Date.now()
        ? await aws.refresh(saved.value.session)
        : saved.value.session;
    await aws.listAccounts(session);
    if (session !== saved.value.session)
      await writePrivate(
        ctx.sql,
        "identity_sessions",
        owner(ctx),
        input.ref,
        { ...saved.value, session },
        saved.revision,
      );
    return {};
  },
};

/**
 * AWS-owned pages a device sign-in may send a person to. The OIDC service names the page, but
 * Basalt shows it as a link, so only exact AWS hosts in the connection's own region pass.
 *
 * - Sign-in platform: `https://<region>.signin.aws/platform/authorize?request_uri=urn:ietf:params:oauth:request_uri:…`
 *   (also `<region>.sso.signin.aws`). The request URI carries the code, so the link has no user_code.
 * - Instance portal: `https://ssoins-<instance id>.<region>.portal.amazonaws.com/#/device?user_code=…`
 * - Legacy: `https://device.sso.<region>.amazonaws.com/?user_code=…`
 */
// Instance IDs use [a-zA-Z0-9-.]{16}; a dot would add a DNS label and URL lowercases hosts.
const instancePortal = /^ssoins-[a-z0-9-]{16}\.([a-z0-9-]+)\.portal\.amazonaws\.com$/u;
const userCode = /^[A-Za-z0-9-]+$/u;
// A pushed authorization request URN with its opaque, URL-safe reference.
const pushedRequest = /^urn:ietf:params:oauth:request_uri:[A-Za-z0-9._~-]+$/u;

/** The parsed page when `value` is an AWS device sign-in page for `region`; otherwise undefined. */
export const deviceVerificationUrl = (
  value: string,
  region: string,
  kind: "page" | "complete",
): URL | undefined => {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return undefined;
  }
  if (
    url.protocol !== "https:" ||
    url.username !== "" ||
    url.password !== "" ||
    url.port !== ""
  )
    return undefined;
  if (url.hostname === `device.sso.${region}.amazonaws.com`) return url;
  if (url.hostname === `${region}.signin.aws` || url.hostname === `${region}.sso.signin.aws`)
    return url.pathname === "/platform/authorize" &&
      url.hash === "" &&
      pushedRequest.test(url.searchParams.get("request_uri") ?? "")
      ? url
      : undefined;
  if (instancePortal.exec(url.hostname)?.[1] !== region) return undefined;
  if (url.pathname !== "/" || url.search !== "") return undefined;
  const fragment = /^#\/device(?:\?user_code=([^&#]*))?$/u.exec(url.hash);
  if (fragment === null) return undefined;
  const code = fragment[1];
  if (code === undefined) return kind === "page" ? url : undefined;
  return userCode.test(code) ? url : undefined;
};

/** AWS Identity Center protocol failure safe to show in logs or a user-facing recovery state. */
export type AwsIdentityFailure =
  | "invalid_start_url"
  | "invalid_region"
  | "wrong_region"
  | "authorization_pending"
  | "slow_down"
  | "authorization_denied"
  | "device_code_expired"
  | "session_expired"
  | "access_denied"
  | "no_access"
  | "rate_limited"
  | "unavailable"
  | "invalid_response"
  | "request_failed";

const recovery: Record<AwsIdentityFailure, string> = {
  invalid_start_url: "Use the AWS access portal address ending in /start.",
  invalid_region: "Check the AWS Identity Center region and try again.",
  wrong_region: "Use the region where your AWS access portal is configured.",
  authorization_pending: "Finish signing in through AWS and your company's sign-in page.",
  slow_down: "AWS asked us to wait longer before checking sign-in again.",
  authorization_denied: "Sign-in was denied. Start again if you want to connect AWS.",
  device_code_expired: "The sign-in link expired. Start again to get a new link.",
  session_expired: "Sign in to AWS again to continue.",
  access_denied:
    "AWS did not allow this account or role. Choose an assigned role or ask your administrator about access.",
  no_access: "AWS returned no accounts or roles for this sign-in.",
  rate_limited: "AWS is receiving too many requests. Try again shortly.",
  unavailable: "AWS is temporarily unavailable. Keep this connection and try again shortly.",
  invalid_response:
    "AWS returned a response this connection could not use. Keep the connection and retry.",
  request_failed: "AWS could not complete this request. Keep the connection and retry.",
};

export class AwsIdentityError extends Error {
  readonly name = "AwsIdentityError";
  constructor(
    readonly failure: AwsIdentityFailure,
    readonly retryable: boolean,
  ) {
    super(recovery[failure]);
  }
}

const commercialRegions = new Set([
  "af-south-1",
  "ap-east-1",
  "ap-east-2",
  "ap-northeast-1",
  "ap-northeast-2",
  "ap-northeast-3",
  "ap-south-1",
  "ap-south-2",
  "ap-southeast-1",
  "ap-southeast-2",
  "ap-southeast-3",
  "ap-southeast-4",
  "ap-southeast-5",
  "ap-southeast-6",
  "ap-southeast-7",
  "ca-central-1",
  "ca-west-1",
  "eu-central-1",
  "eu-central-2",
  "eu-north-1",
  "eu-south-1",
  "eu-south-2",
  "eu-west-1",
  "eu-west-2",
  "eu-west-3",
  "il-central-1",
  "me-central-1",
  "me-south-1",
  "mx-central-1",
  "sa-east-1",
  "us-east-1",
  "us-east-2",
  "us-west-1",
  "us-west-2",
]);

export const validateStartUrl = (value: string): URL => {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new AwsIdentityError("invalid_start_url", false);
  }
  if (
    url.protocol !== "https:" ||
    url.username !== "" ||
    url.password !== "" ||
    url.port !== "" ||
    url.search !== "" ||
    url.hash !== "" ||
    !/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+awsapps\.com$/u.test(url.hostname) ||
    url.pathname !== "/start"
  )
    throw new AwsIdentityError("invalid_start_url", false);
  return url;
};

export const validateRegion = (region: string): string => {
  if (!commercialRegions.has(region)) throw new AwsIdentityError("invalid_region", false);
  return region;
};

export const icons = [
  {
    src: "data:image/png;base64,",
    mimeType: "image/png",
    theme: "light",
  },
  {
    src: "data:image/png;base64,",
    mimeType: "image/png",
    theme: "dark",
  },
] as const;

import { AwsIdentityError, validateRegion, validateStartUrl } from "./errors.ts";
export { AwsIdentityError } from "./errors.ts";
export type { AwsIdentityFailure } from "./errors.ts";

import {
  Registered,
  Device,
  Token,
  AccountsPage,
  RolesPage,
  RoleCredentials,
  parse,
  type RegisteredClient,
  type IdentityClientSession,
  type DeviceAuthorization,
  type IdentitySession,
  type AssignedAccount,
  type AssignedRole,
  type TemporaryRoleCredentials,
} from "./identity-schema.ts";
export {
  RegisteredClientSchema,
  DeviceAuthorizationSchema,
  TokenSetSchema,
  IdentitySessionSchema,
  PendingIdentitySessionSchema,
} from "./identity-schema.ts";
export type {
  RegisteredClient,
  IdentityClientSession,
  DeviceAuthorization,
  PendingIdentitySession,
  TokenSet,
  IdentitySession,
  AssignedAccount,
  AssignedRole,
  TemporaryRoleCredentials,
} from "./identity-schema.ts";
import { identityHttp } from "./identity-http.ts";
import { deviceVerificationUrl } from "./device-url.ts";

type WireEndpoints = { readonly oidc: string; readonly portal: string };
type ClientOptions = {
  readonly fetch: typeof globalThis.fetch;
  /** Test fixture override only. Production callers derive these from the validated region. */
  readonly endpoints?: WireEndpoints | undefined;
  readonly now?: () => number;
};
const MAX_PAGES = 100;
/** Stateless AWS Identity Center API client. Persist its session only in private server storage. */
export const makeIdentityCenter = (
  input: { readonly region: string; readonly startUrl: string } & ClientOptions,
) => {
  const region = validateRegion(input.region);
  const startUrl = validateStartUrl(input.startUrl).href;
  const endpoints = input.endpoints ?? {
    oidc: `https://oidc.${region}.amazonaws.com`,
    portal: `https://portal.sso.${region}.amazonaws.com`,
  };
  const now = input.now ?? Date.now;
  const { post, get } = identityHttp(input.fetch);
  const oidc = (path: string) => `${endpoints.oidc.replace(/\/$/u, "")}${path}`;
  const portal = (path: string) => `${endpoints.portal.replace(/\/$/u, "")}${path}`;

  const register = async (): Promise<RegisteredClient> =>
    parse(
      Registered,
      await post(oidc("/client/register"), {
        clientName: "Basalt AWS connection",
        clientType: "public",
        grantTypes: ["urn:ietf:params:oauth:grant-type:device_code", "refresh_token"],
        scopes: ["sso:account:access"],
      }),
    );

  const begin = async (): Promise<{
    readonly client: IdentityClientSession;
    readonly device: DeviceAuthorization;
  }> => {
    const registered = await register();
    const client: IdentityClientSession = { ...registered, region, startUrl };
    const raw = parse(
      Device,
      await post(oidc("/device_authorization"), {
        clientId: client.clientId,
        clientSecret: client.clientSecret,
        startUrl,
      }),
    );
    const complete = deviceVerificationUrl(raw.verificationUriComplete, region, "complete");
    if (!complete || !deviceVerificationUrl(raw.verificationUri, region, "page"))
      throw new AwsIdentityError("invalid_response", false);
    return {
      client,
      device: {
        deviceCode: raw.deviceCode,
        userCode: raw.userCode,
        verificationUri: raw.verificationUri,
        verificationUriComplete: complete.href,
        expiresAt: now() + raw.expiresIn * 1_000,
        intervalSeconds: Math.max(1, raw.interval ?? 5),
      },
    };
  };

  /** One interval-respecting device poll. Caller schedules the next check from retryAfterSeconds. */
  const poll = async (
    session: IdentityClientSession,
    deviceCode: string,
    intervalSeconds: number,
    deviceExpiresAt: number,
  ): Promise<
    | { readonly state: "pending"; readonly retryAfterSeconds: number }
    | { readonly state: "authorized"; readonly session: IdentitySession }
  > => {
    if (now() >= deviceExpiresAt) throw new AwsIdentityError("device_code_expired", false);
    try {
      const token = parse(
        Token,
        await post(
          oidc("/token"),
          {
            clientId: session.clientId,
            clientSecret: session.clientSecret,
            grantType: "urn:ietf:params:oauth:grant-type:device_code",
            deviceCode,
          },
          {},
          "poll",
        ),
      );
      return {
        state: "authorized",
        session: {
          ...session,
          ...token,
          accessTokenExpiresAt: now() + token.expiresIn * 1_000,
          ...(token.refreshTokenExpiresIn === undefined
            ? {}
            : { refreshTokenExpiresAt: now() + token.refreshTokenExpiresIn * 1_000 }),
        },
      };
    } catch (error) {
      if (!(error instanceof AwsIdentityError)) throw error;
      if (error.failure === "authorization_pending")
        return { state: "pending", retryAfterSeconds: intervalSeconds };
      if (error.failure === "slow_down")
        return { state: "pending", retryAfterSeconds: intervalSeconds + 5 };
      throw error;
    }
  };

  const refresh = async (session: IdentitySession): Promise<IdentitySession> => {
    if (
      session.refreshToken === undefined ||
      (session.refreshTokenExpiresAt !== undefined && now() >= session.refreshTokenExpiresAt)
    )
      throw new AwsIdentityError("session_expired", false);
    const token = parse(
      Token,
      await post(
        oidc("/token"),
        {
          clientId: session.clientId,
          clientSecret: session.clientSecret,
          grantType: "refresh_token",
          refreshToken: session.refreshToken,
        },
        {},
        "refresh",
      ),
    );
    return {
      ...session,
      ...token,
      refreshToken: token.refreshToken ?? session.refreshToken,
      accessTokenExpiresAt: now() + token.expiresIn * 1_000,
      ...(token.refreshTokenExpiresIn === undefined
        ? {}
        : { refreshTokenExpiresAt: now() + token.refreshTokenExpiresIn * 1_000 }),
    };
  };

  const bearerHeaders = (session: IdentitySession) => ({
    "x-amz-sso_bearer_token": session.accessToken,
  });
  const pageThrough = async <A>(
    path: string,
    base: Record<string, string>,
    decode: (value: unknown) => {
      readonly rows: readonly A[];
      readonly nextToken?: string | undefined;
    },
    session: IdentitySession,
  ): Promise<A[]> => {
    const values: A[] = [],
      seen = new Set<string>();
    let nextToken: string | undefined;
    for (let page = 0; page < MAX_PAGES; page++) {
      const query = new URLSearchParams({
        ...base,
        max_result: "100",
        ...(nextToken === undefined ? {} : { next_token: nextToken }),
      });
      const result = decode(
        await get(`${portal(path)}?${query}`, bearerHeaders(session), "accounts"),
      );
      values.push(...result.rows);
      nextToken = result.nextToken;
      if (nextToken === undefined || nextToken === "") return values;
      if (seen.has(nextToken)) throw new AwsIdentityError("invalid_response", false);
      seen.add(nextToken);
    }
    throw new AwsIdentityError("invalid_response", false);
  };

  const listAccounts = async (session: IdentitySession): Promise<readonly AssignedAccount[]> => {
    const accounts = await pageThrough(
      "/assignment/accounts",
      {},
      (value) => {
        const page = parse(AccountsPage, value);
        return { rows: page.accountList, nextToken: page.nextToken };
      },
      session,
    );
    if (accounts.some((account) => !/^\d{12}$/u.test(account.accountId)))
      throw new AwsIdentityError("invalid_response", false);
    if (accounts.length === 0) throw new AwsIdentityError("no_access", false);
    return accounts;
  };
  const listRoles = async (
    session: IdentitySession,
    accountId: string,
  ): Promise<readonly AssignedRole[]> => {
    if (!/^\d{12}$/u.test(accountId)) throw new AwsIdentityError("access_denied", false);
    const roles = await pageThrough(
      "/assignment/roles",
      { account_id: accountId },
      (value) => {
        const page = parse(RolesPage, value);
        return { rows: page.roleList, nextToken: page.nextToken };
      },
      session,
    );
    if (roles.some((role) => role.accountId !== undefined && role.accountId !== accountId))
      throw new AwsIdentityError("invalid_response", false);
    return roles.map((role) => ({ ...role, accountId }));
  };
  const getRoleCredentials = async (
    session: IdentitySession,
    accountId: string,
    roleName: string,
  ): Promise<TemporaryRoleCredentials> => {
    if (!/^\d{12}$/u.test(accountId) || roleName.length < 1 || roleName.length > 128)
      throw new AwsIdentityError("access_denied", false);
    const query = new URLSearchParams({ account_id: accountId, role_name: roleName });
    const raw = parse(
      RoleCredentials,
      await get(
        `${portal("/federation/credentials")}?${query}`,
        bearerHeaders(session),
        "credentials",
      ),
    );
    if (raw.roleCredentials.expiration <= now())
      throw new AwsIdentityError("session_expired", true);
    return { ...raw.roleCredentials, expiresAt: raw.roleCredentials.expiration };
  };

  return { region, startUrl, begin, poll, refresh, listAccounts, listRoles, getRoleCredentials };
};

import { AwsIdentityError } from "./errors.ts";

const MAX_BODY_BYTES = 1_000_000;
const safeCode = (value: unknown): string => (typeof value === "string" ? value : "");
const failureFor = (
  status: number,
  code: string,
  action: "start" | "poll" | "refresh" | "accounts" | "roles" | "credentials",
): AwsIdentityError => {
  const normalized = code
    .replace(/Exception$/u, "")
    .replace(/[^A-Za-z]/gu, "")
    .toLowerCase();
  if (["wrongregion", "invalidrequestregion", "regionnotsupported"].includes(normalized))
    return new AwsIdentityError("wrong_region", false);
  if (["authorizationpending", "pendingauthorization"].includes(normalized))
    return new AwsIdentityError("authorization_pending", true);
  if (normalized === "slowdown") return new AwsIdentityError("slow_down", true);
  if (["accessdenied", "authorizationdeclined"].includes(normalized))
    return new AwsIdentityError(
      action === "poll" ? "authorization_denied" : "access_denied",
      false,
    );
  if (["expiredtoken", "authorizationexpired"].includes(normalized))
    return new AwsIdentityError(
      action === "poll" ? "device_code_expired" : "session_expired",
      false,
    );
  if (["unauthorized", "forbidden", "invalidgrant"].includes(normalized))
    return new AwsIdentityError("session_expired", false);
  if (
    ["toomanyrequests", "throttling", "throttlingexception"].includes(normalized) ||
    status === 429
  )
    return new AwsIdentityError("rate_limited", true);
  if (status >= 500) return new AwsIdentityError("unavailable", true);
  return new AwsIdentityError("request_failed", false);
};

/** JSON over the host fetch policy; AWS errors leave through safe recovery states. */
export const identityHttp = (fetcher: typeof globalThis.fetch) => {
  const request = async (
    url: string,
    init: RequestInit,
    action: Parameters<typeof failureFor>[2] = "start",
  ) => {
    let response: Response;
    try {
      response = await fetcher(url, init);
    } catch {
      throw new AwsIdentityError("unavailable", true);
    }
    const text = await response.text();
    if (new TextEncoder().encode(text).byteLength > MAX_BODY_BYTES)
      throw new AwsIdentityError("invalid_response", false);
    let value: unknown;
    try {
      // AWS JSON protocols may send null for an unset optional member; decoders expect absence.
      value = text === "" ? {} : JSON.parse(text, (_key, field) => field ?? undefined);
    } catch {
      throw new AwsIdentityError("invalid_response", false);
    }
    if (!response.ok) {
      const record =
        typeof value === "object" && value !== null ? (value as Record<string, unknown>) : {};
      throw failureFor(
        response.status,
        safeCode(record.error ?? record.code ?? record.__type),
        action,
      );
    }
    return value;
  };
  const post = (
    url: string,
    body: unknown,
    headers: Record<string, string> = {},
    action: Parameters<typeof failureFor>[2] = "start",
  ) =>
    request(
      url,
      {
        method: "POST",
        headers: { "content-type": "application/json", ...headers },
        body: JSON.stringify(body),
      },
      action,
    );
  const get = (
    url: string,
    headers: Record<string, string> = {},
    action: Parameters<typeof failureFor>[2] = "accounts",
  ) => request(url, { method: "GET", headers }, action);
  return { post, get };
};

