import { AwsIdentityError } from "./errors.ts";
export class ChoiceRequired extends Error {
  readonly name = "ChoiceRequired";
}
export const safeResult = async <A>(work: () => Promise<A>) => {
  try {
    return { ok: true as const, value: await work() };
  } catch (error) {
    if (error instanceof AwsIdentityError)
      return {
        ok: false as const,
        state: error.failure,
        message: error.message,
        retryable: error.retryable,
      };
    if (error instanceof ChoiceRequired)
      return {
        ok: false as const,
        state: "choice_required",
        message: error.message,
        retryable: false,
      };
    return {
      ok: false as const,
      state: "unavailable",
      message:
        "AWS could not complete this request. Keep your connection and retry. No different account or role was selected.",
      retryable: true,
    };
  }
};

/** Saved connection ownership, refresh and visible recovery state. */
import type { MutationContext, QueryContext } from "apps";
import { requirements } from "./requirements.ts";
import { makeIdentityCenter } from "./identity-client.ts";
import { AwsIdentityError } from "./errors.ts";
import { identityEndpoints } from "./wire.ts";
import { readPrivate, writePrivate, claimPrivate } from "./session-store.ts";
import { SavedSession } from "./identity-state.ts";
import { ChoiceRequired } from "./safe-result.ts";
type Context = MutationContext<typeof requirements>;
type ReadContext = QueryContext<typeof requirements>;
const accountFor = (ctx: ReadContext, connection?: string) => {
  const accounts = ctx.user.accounts.identityCenter.filter(
    (account) => account.method === "identityCenter",
  );
  const matches =
    connection === undefined ? accounts : accounts.filter((account) => account.id === connection);
  if (matches.length !== 1)
    throw new ChoiceRequired(
      matches.length === 0
        ? "Connect AWS Identity Center in Accounts first."
        : "Choose the saved AWS connection for this task.",
    );
  const account = matches[0];
  if (account?.method !== "identityCenter")
    throw new ChoiceRequired("Choose an AWS Identity Center connection.");
  if (!ctx.user.id) throw new ChoiceRequired("Sign in to use your AWS connection.");
  return { account, owner: ctx.user.id, reference: account.fields.ref };
};
export const load = async (ctx: ReadContext, connection?: string) => {
  const selected = accountFor(ctx, connection),
    stored = await readPrivate(
      ctx.sql,
      "identity_sessions",
      selected.owner,
      selected.reference,
      SavedSession,
    );
  if (!stored) throw new AwsIdentityError("session_expired", false);
  return { ...selected, ...stored };
};
/** Keep the connection and choices when AWS revokes a session. A newer sign-in wins the revision check. */
export const sessionRequest = async <A>(
  ctx: Context,
  stored: Awaited<ReturnType<typeof load>>,
  work: () => Promise<A>,
) => {
  try {
    return await work();
  } catch (error) {
    if (error instanceof AwsIdentityError && error.failure === "session_expired")
      await writePrivate(
        ctx.sql,
        "identity_sessions",
        stored.owner,
        stored.reference,
        { ...stored.value, reauthenticationRequired: true },
        stored.revision,
      );
    throw error;
  }
};
export const awsFor = (ctx: ReadContext, state: SavedSession) =>
  makeIdentityCenter({ ...state.session, fetch: ctx.fetch, endpoints: identityEndpoints() });
/** Refresh has one claim. A failed or concurrent refresh never replaces a newer saved session. */
export const fresh = async (ctx: Context, connection?: string) => {
  let stored = await load(ctx, connection);
  if (stored.value.reauthenticationRequired) throw new AwsIdentityError("session_expired", false);
  if (stored.value.session.accessTokenExpiresAt > Date.now() + 30_000) return stored;
  const release = claimPrivate(
    ctx.sql,
    "identity_sessions",
    stored.owner,
    stored.reference,
    stored.revision,
  );
  try {
    const session = await sessionRequest(ctx, stored, () =>
      awsFor(ctx, stored.value).refresh(stored.value.session),
    );
    await writePrivate(
      ctx.sql,
      "identity_sessions",
      stored.owner,
      stored.reference,
      { ...stored.value, session },
      stored.revision,
    );
    stored = await load(ctx, connection);
    return stored;
  } finally {
    release();
  }
};
export const publicConnection = (connection: string, state: SavedSession) => ({
  connection,
  startUrl: state.session.startUrl,
  region: state.session.region,
  expiresAt: state.session.accessTokenExpiresAt,
  accounts: state.accounts,
  defaultTarget: state.defaultTarget ?? null,
  state:
    !state.reauthenticationRequired &&
    (state.session.accessTokenExpiresAt > Date.now() ||
      (state.session.refreshToken !== undefined &&
        state.session.clientSecretExpiresAt * 1000 > Date.now() &&
        (state.session.refreshTokenExpiresAt === undefined ||
          state.session.refreshTokenExpiresAt > Date.now())))
      ? "connected"
      : "session_expired",
});

/** Session keys stay in the host-encrypted account reference, outside app SQL. */
import { object, string, number, jsonSchema, type Schema } from "apps";
import type { Sql, SqlReader } from "apps/contracts";

const hex = (bytes: Uint8Array) =>
  Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
const bytes = (text: string) =>
  Uint8Array.from(text.match(/../gu) ?? [], (byte) => Number.parseInt(byte, 16));
const Reference = /^sso:([0-9a-f-]{36}):([0-9a-f]{64})$/u;
const Stored = object({
  ciphertext: string(),
  revision: number(),
  lease: jsonSchema({ type: ["string", "null"] }),
  lease_until: number(),
});
export type PrivateTable = "identity_sessions" | "identity_attempts";
export const newReference = () =>
  `sso:${crypto.randomUUID()}:${hex(crypto.getRandomValues(new Uint8Array(32)))}`;
const parts = (reference: string) => {
  const match = Reference.exec(reference);
  if (!match?.[1] || !match[2])
    throw new Error(
      "The saved AWS connection reference is invalid. Re-sign in without deleting the account.",
    );
  return { id: match[1], key: bytes(match[2]) };
};
const cipherKey = (key: Uint8Array<ArrayBuffer>) =>
  crypto.subtle.importKey("raw", key, "AES-GCM", false, ["encrypt", "decrypt"]);
const seal = async (owner: string, reference: string, value: unknown) => {
  const { id, key } = parts(reference),
    nonce = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv: nonce, additionalData: new TextEncoder().encode(`${owner}:${id}`) },
    await cipherKey(key),
    new TextEncoder().encode(JSON.stringify(value)),
  );
  return `${hex(nonce)}:${hex(new Uint8Array(ciphertext))}`;
};
export const readPrivate = async <A>(
  sql: SqlReader,
  table: PrivateTable,
  owner: string,
  reference: string,
  schema: Schema<A>,
) => {
  const { id, key } = parts(reference);
  const row = sql
    .exec(
      `SELECT ciphertext, revision, lease, lease_until FROM ${table} WHERE id = ? AND owner = ?`,
      id,
      owner,
    )
    .toArray()[0];
  if (!row) return undefined;
  const stored = Stored.parse(row),
    [nonce, ciphertext] = stored.ciphertext.split(":");
  if (!nonce || !ciphertext)
    throw new Error(
      "The saved AWS session could not be read. Re-sign in without deleting the account.",
    );
  const plaintext = await crypto.subtle.decrypt(
    {
      name: "AES-GCM",
      iv: bytes(nonce),
      additionalData: new TextEncoder().encode(`${owner}:${id}`),
    },
    await cipherKey(key),
    bytes(ciphertext),
  );
  const value = schema.parse(JSON.parse(new TextDecoder().decode(plaintext)));
  return {
    value,
    revision: stored.revision,
    busy: stored.lease !== null && stored.lease_until > Date.now(),
  };
};
/** Replace only the revision the caller actually read; never overwrite another refresh or sign-in. */
export const writePrivate = async (
  sql: Sql,
  table: PrivateTable,
  owner: string,
  reference: string,
  value: unknown,
  revision?: number,
) => {
  const { id } = parts(reference),
    ciphertext = await seal(owner, reference, value);
  if (revision === undefined) {
    sql.exec(`INSERT INTO ${table} (id,owner,ciphertext) VALUES (?,?,?)`, id, owner, ciphertext);
    return;
  }
  const saved = sql.exec(
    `UPDATE ${table} SET ciphertext = ?, revision = revision + 1, lease = NULL, lease_until = 0 WHERE id = ? AND owner = ? AND revision = ?`,
    ciphertext,
    id,
    owner,
    revision,
  );
  if (saved.rowsWritten !== 1)
    throw new Error("AWS sign-in changed while this request was running. Retry the request.");
};
export const removePrivate = (sql: Sql, table: PrivateTable, owner: string, reference: string) => {
  sql.exec(`DELETE FROM ${table} WHERE id = ? AND owner = ?`, parts(reference).id, owner);
};
/** A refresh claim ends before the host's invocation deadline; no SQL transaction spans HTTP. */
export const claimPrivate = (
  sql: Sql,
  table: PrivateTable,
  owner: string,
  reference: string,
  revision: number,
) => {
  const lease = crypto.randomUUID(),
    now = Date.now();
  const claimed = sql.exec(
    `UPDATE ${table} SET lease = ?, lease_until = ? WHERE id = ? AND owner = ? AND revision = ? AND (lease IS NULL OR lease_until < ?)`,
    lease,
    now + 15_000,
    parts(reference).id,
    owner,
    revision,
    now,
  );
  if (claimed.rowsWritten !== 1)
    throw new Error("AWS session refresh is already running. Retry the request shortly.");
  return () => {
    sql.exec(
      `UPDATE ${table} SET lease = NULL, lease_until = 0 WHERE id = ? AND owner = ? AND lease = ?`,
      parts(reference).id,
      owner,
      lease,
    );
  };
};

/* The approved dark AWS accounts mock (carry 0402), without the host shell it was drawn inside. */
:root {
  color-scheme: dark;
  --bg: #171717;
  --panel: #202020;
  --line: #393939;
  --row: #343434;
  --field: #242424;
  --field-line: #505050;
  --muted: #b1b1b1;
  --fg: #f3f3f3;
  --accent: #e8e8e8;
  --amber: #f4bf69;
  --green: #9dceae;
  --focus: #b6d5ff;
  --control: 40px;
  --row-control: 36px;
}
* {
  box-sizing: border-box;
}
html,
body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font:
    14px/1.5 -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  -webkit-text-size-adjust: 100%;
}
button,
input,
select {
  font: inherit;
}
button,
a,
input,
select,
summary {
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
button,
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: var(--control);
  padding: 9px 14px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #292929;
  color: var(--fg);
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
}
button:hover:not(:disabled),
.button:hover {
  background: #353535;
}
.primary {
  background: var(--accent);
  color: #191919;
  border-color: var(--accent);
  font-weight: 600;
}
.primary:hover:not(:disabled),
.button.primary:hover {
  background: #fff;
}
.quiet {
  background: transparent;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
}
select {
  width: 100%;
  min-width: 0;
  min-height: var(--control);
  border: 1px solid var(--field-line);
  border-radius: 6px;
  background: var(--field);
  color: var(--fg);
  padding: 8px 10px;
}
select:disabled {
  opacity: 0.55;
}
input[type="checkbox"] {
  width: 18px;
  height: 18px;
  margin: 2px 0 0;
  flex: none;
  accent-color: var(--accent);
}
h1 {
  font-size: 19px;
  line-height: 1.3;
  margin: 0 0 8px;
  letter-spacing: -0.015em;
}
h2 {
  font-size: 15px;
  line-height: 1.35;
  margin: 0 0 4px;
}
h3 {
  font-size: 14px;
  margin: 0 0 4px;
}
p {
  margin: 0 0 14px;
}
small,
.muted {
  color: var(--muted);
}
small {
  display: block;
  font-size: 12px;
}
code,
pre {
  font:
    12px/1.5 ui-monospace,
    "SF Mono",
    Menlo,
    monospace;
}
.min0 {
  min-width: 0;
  overflow-wrap: anywhere;
}
.row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.page {
  max-width: 930px;
  padding: 32px 40px 64px;
}
.intro {
  max-width: 650px;
}
.connection {
  max-width: 850px;
  margin-top: 22px;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: 9px;
}
.connection.empty {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.connection.empty p {
  margin: 0;
  max-width: 60ch;
}
.connectionhead {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 18px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--line);
}
.connectionhead .url {
  margin-top: 1px;
}
.headactions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}
.status {
  margin-top: 4px;
  color: var(--green);
  font-size: 12px;
}
.status.expired {
  color: var(--amber);
}
.loading {
  margin: 18px 0 0;
}
.badge {
  display: inline-block;
  margin-left: 4px;
  padding: 2px 6px;
  border: 1px solid #615239;
  border-radius: 4px;
  color: var(--amber);
  font-size: 11px;
  white-space: nowrap;
  vertical-align: 1px;
}
.accounts {
  margin: 0;
  padding: 0;
  list-style: none;
}
.account {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 190px 116px;
  align-items: center;
  gap: 14px;
  padding: 13px 0;
  border-bottom: 1px solid var(--row);
}
.account:last-child {
  border-bottom: 0;
}
.account strong {
  font-weight: 500;
}
.account small {
  margin-top: 2px;
}
.account select,
.account button {
  min-height: var(--row-control);
  font-size: 12px;
}
.account select {
  padding: 5px 8px;
}
.account button {
  padding: 6px 8px;
}
.role {
  font-size: 12px;
  color: var(--muted);
  overflow-wrap: anywhere;
  padding: 0 9px;
}
.defaultmark {
  justify-self: center;
  font-size: 12px;
  font-weight: 600;
  color: var(--green);
}
.id {
  font-variant-numeric: tabular-nums;
  user-select: all;
}
.note {
  margin-top: 16px;
  color: var(--muted);
  font-size: 12px;
}
.note span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.linkbutton {
  min-height: var(--row-control);
  padding: 3px;
  border: 0;
  background: transparent;
  color: #ccc;
  font-size: 12px;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.linkbutton:hover:not(:disabled) {
  background: transparent;
  color: #fff;
}
.help {
  margin-top: 20px;
  padding-top: 15px;
  border-top: 1px solid var(--line);
  font-size: 13px;
}
.help summary {
  cursor: pointer;
  color: #ddd;
  min-height: 28px;
}
.help p {
  margin-top: 12px;
  color: var(--muted);
  max-width: 70ch;
}
.production {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
}
.production label {
  cursor: pointer;
}
.access {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}
.access > p {
  font-size: 13px;
  max-width: 70ch;
}
.fields {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) auto;
  align-items: end;
  gap: 12px;
}
.field label {
  display: block;
  margin-bottom: 6px;
  font-weight: 500;
}
.notice {
  margin: 18px 0 0;
  padding: 14px;
  border: 1px solid #615239;
  border-radius: 7px;
  background: #2e2820;
  color: #f0d2a2;
  overflow-wrap: anywhere;
}
.notice p {
  margin: 0;
}
.notice p + p {
  margin-top: 6px;
}
.notice.good {
  border-color: #415c49;
  background: #222c25;
  color: #b7d6c0;
}
.noticetitle {
  display: block;
  margin-bottom: 4px;
  color: #fbe3bd;
}
.noticeactions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}
.receipt {
  margin-top: 18px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #191919;
}
.receipt dl {
  display: grid;
  grid-template-columns: 90px minmax(0, 1fr);
  gap: 9px 14px;
  margin: 12px 0 0;
}
.receipt dt {
  color: var(--muted);
}
.receipt dd {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
}
.receipt .help {
  margin-top: 16px;
}
.receipt pre {
  max-height: 240px;
  margin: 10px 0 0;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--fg);
}
.check {
  color: var(--green);
}
.refused {
  color: var(--amber);
}
@media (max-width: 650px) {
  :root {
    --control: 44px;
    --row-control: 44px;
  }
  .page {
    padding: 23px 18px 48px;
  }
  .connection {
    padding: 16px;
  }
  .connection.empty {
    flex-direction: column;
    align-items: stretch;
  }
  .connectionhead {
    flex-direction: column;
  }
  .headactions {
    width: 100%;
    justify-content: stretch;
  }
  .headactions > * {
    flex: 1;
  }
  /* Below 16px, iOS zooms the page when a select gains focus. */
  select,
  .account select {
    font-size: 16px;
  }
  .account {
    grid-template-columns: minmax(0, 1fr) 104px;
    gap: 8px;
  }
  .account > .min0 {
    grid-column: 1 / -1;
  }
  .fields {
    grid-template-columns: minmax(0, 1fr);
  }
  .noticeactions > * {
    flex: 1;
  }
  .receipt dl {
    grid-template-columns: 76px minmax(0, 1fr);
    gap: 10px;
  }
}
@media (pointer: coarse) {
  :root {
    --row-control: 44px;
  }
}

